import streamlit as st
import streamlit.components.v1 as components

# AFTERIMAGE. — single-file Streamlit prototype.
# The generated flower artwork is embedded in this file; no extra image file is needed.

st.set_page_config(page_title="AFTERIMAGE.", page_icon="✳", layout="wide")

if "page" not in st.session_state:
    st.session_state.page = "landing"

LANDING_IMAGE = "data:image/jpeg;base64,"

st.markdown("""
<style>
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;400;500&family=Playfair+Display:wght@400;500&display=swap');
[data-testid="stAppViewContainer"], [data-testid="stHeader"] {background:#090909;}
[data-testid="stHeader"] {height:0;}
[data-testid="stToolbar"], [data-testid="stSidebar"] {visibility:hidden;}
.block-container {max-width:100% !important;padding:0 !important;}
.stButton > button {
    border-radius:0 !important;border:1px solid #d8c33a !important;
    background:transparent !important;color:#f0d52f !important;
    min-height:46px;font-family:'DM Sans',sans-serif !important;
    font-size:10px !important;letter-spacing:2px !important;
    transition:.25s ease;
}
.stButton > button:hover {background:#f0d52f !important;color:#090909 !important;}
</style>
""", unsafe_allow_html=True)


def landing_page():
    components.html(
        f"""
        <!doctype html>
        <html>
        <head>
        <meta name="viewport" content="width=device-width, initial-scale=1">
        <style>
            * {{box-sizing:border-box;}}
            html, body {{margin:0;padding:0;background:#090909;width:100%;overflow:hidden;}}
            img {{display:block;width:100%;height:auto;object-fit:contain;}}
        </style>
        </head>
        <body>
            <img src="{LANDING_IMAGE}" alt="AFTERIMAGE. monochrome flower landing design">
        </body>
        </html>
        """,
        height=560,
        scrolling=False
    )

    st.markdown(
        "<div style='text-align:center;color:#aaa;font:10px DM Sans;letter-spacing:3px;margin:8px 0 14px'>"
        "CHOOSE YOUR NEXT SPACE</div>",
        unsafe_allow_html=True
    )
    left, center1, center2, right = st.columns([2, 1.6, 1.6, 2])
    with center1:
        if st.button("START EXHIBITION  ↗", use_container_width=True):
            st.session_state.page = "studio"
            st.rerun()
    with center2:
        if st.button("EXPLORE EXHIBITIONS", use_container_width=True):
            st.session_state.page = "explore"
            st.rerun()


def inner_page(title, description):
    st.markdown(f"""
    <div style="min-height:85vh;background:#f6f5f1;color:#171717;padding:54px 8%;font-family:'DM Sans',sans-serif;">
        <div style="font-family:'Playfair Display',serif;color:#b39e27;font-size:24px;letter-spacing:1px;">AFTERIMAGE.</div>
        <div style="margin-top:75px;font-family:'Playfair Display',serif;font-size:clamp(42px,6vw,76px);font-weight:400;">{title}</div>
        <div style="margin-top:15px;color:#777;font-size:14px;">{description}</div>
        <div style="margin-top:55px;border-top:1px solid #dedbd2;padding-top:22px;color:#999;font-size:10px;letter-spacing:2px;">YOUR ART. YOUR WORLD.</div>
    </div>
    """, unsafe_allow_html=True)

    col1, col2, col3 = st.columns([1, 1, 1])
    with col2:
        if st.button("← BACK TO HOME", use_container_width=True):
            st.session_state.page = "landing"
            st.rerun()


if st.session_state.page == "landing":
    landing_page()
elif st.session_state.page == "studio":
    inner_page("MY STUDIO", "Manage and organize your creative projects.")
elif st.session_state.page == "explore":
    inner_page("EXPLORE", "Discover exhibitions and creative worlds.")
